import struct, zlib
def decode(path):
    data = open(path,'rb').read()
    assert data[:8] == b'\x89PNG\r\n\x1a\n'
    pos = 8; idat = b''; w=h=None; ctype=None; bitd=None
    while pos < len(data):
        ln, typ = struct.unpack('>I4s', data[pos:pos+8]); pos += 8
        chunk = data[pos:pos+ln]; pos += ln + 4
        if typ == b'IHDR':
            w,h,bitd,ctype = struct.unpack('>IIBB', chunk[:10])
        elif typ == b'IDAT':
            idat += chunk
        elif typ == b'IEND':
            break
    raw = zlib.decompress(idat)
    ch = {6:4,2:3,0:1}[ctype]
    stride = w*ch
    out = bytearray(h*stride)
    prev = bytearray(stride)
    p = 0
    for y in range(h):
        f = raw[p]; p += 1
        line = bytearray(raw[p:p+stride]); p += stride
        if f == 1:
            for i in range(ch, stride): line[i] = (line[i] + line[i-ch]) & 255
        elif f == 2:
            for i in range(stride): line[i] = (line[i] + prev[i]) & 255
        elif f == 3:
            for i in range(stride):
                a = line[i-ch] if i>=ch else 0
                line[i] = (line[i] + ((a + prev[i])>>1)) & 255
        elif f == 4:
            for i in range(stride):
                a = line[i-ch] if i>=ch else 0
                b = prev[i]
                c = prev[i-ch] if i>=ch else 0
                pp = a + b - c
                pa, pb, pc = abs(pp-a), abs(pp-b), abs(pp-c)
                pr = a if (pa<=pb and pa<=pc) else (b if pb<=pc else c)
                line[i] = (line[i] + pr) & 255
        out[y*stride:(y+1)*stride] = line
        prev = line
    return w,h,ch,bytes(out)
def px(w,h,ch,buf,x,y):
    o = (y*w+x)*ch
    return tuple(buf[o:o+ch])
